using HomeLibrary;
using Microsoft.AspNetCore.DataProtection;
using System.Text.Json;
using System.Net.Mail;
public static class HouseholdToolsTests {
 static void Check(bool value,string message){if(!value)throw new Exception("Household tools: "+message);Console.WriteLine("PASS "+message);}
 static JsonElement Input(object value)=>JsonSerializer.SerializeToElement(value,Library.Json);
 static void Reject(Action work){try{work();throw new Exception("Expected rejection");}catch(LibraryError){}}
 public static async Task Run(string directory,IDataProtectionProvider protection){
  Directory.CreateDirectory(directory);using var store=new Store(directory,protection);
  JsonElement Change(string action,object input)=>Input(store.Apply(new(action,Input(input),store.Read().Revision))).GetProperty("result");
  void Add(string title)=>Change("addBook",new{isbn="9780140328721",title,author="Writer",confirmedDuplicates=store.Read().State.Books.Where(b=>!b.Archived).Select(b=>b.Id).ToArray()});
  Add("Original");Change("removeBook",new{copyId="BK-0001"});var deleted=store.Read().State.RecycleBin.Single().Id;Add("Replacement");
  var restored=Change("restoreDeleted",new{deletedId=deleted});Check(restored.GetProperty("id").GetString()=="BK-0002"&&store.Read().State.Books.Single(b=>b.Id=="BK-0001").Title=="Replacement","restoring reused number allocates free ID without overwriting replacement");
  Change("addBorrower",new{name="Reader",contact="reader@example.com",reminderConsent=true});Change("checkout",new{copyId="BK-0001",borrowerId="BR-0001",checkoutDate=Library.Today,dueDate=Library.Today});Reject(()=>Change("removeBook",new{copyId="BK-0001"}));
  Change("returnBook",new{copyId="BK-0001"});Change("removeBook",new{copyId="BK-0001"});var archived=store.Read().State.RecycleBin.Single();Change("restoreDeleted",new{deletedId=archived.Id});Check(store.Read().State.Books.Single(b=>b.Id=="BK-0001").Archived==false&&store.Read().State.Loans.Count==1,"restore referenced book preserves its physical identity and loan history");
  // A prior unreferenced copy's tombstone must not reactivate a different archived replacement.
  Change("removeBook",new{copyId="BK-0002"});var first=store.Read().State.RecycleBin.Single().Id;Add("Later replacement");Change("checkout",new{copyId="BK-0002",borrowerId="BR-0001",checkoutDate=Library.Today});Change("returnBook",new{copyId="BK-0002"});Change("removeBook",new{copyId="BK-0002"});Change("restoreDeleted",new{deletedId=first});Check(store.Read().State.Books.Any(b=>b.Title=="Original"&&!b.Archived)&&store.Read().State.Books.Single(b=>b.Id=="BK-0002").Archived,"old recovery entry cannot restore a different archived replacement");
  var remaining=store.Read().State.RecycleBin.Single();Change("purgeDeleted",new{deletedId=remaining.Id});Check(store.Read().State.RecycleBin.Count==0&&store.Read().State.Books.Single(b=>b.Id=="BK-0002").Archived,"permanent recovery removal preserves required historical archive");Reject(()=>Change("restoreDeleted",new{deletedId=remaining.Id}));
  var before=store.Read().Revision;Reject(()=>Change("bulkEditBooks",new{copyIds=new[]{"BK-0001","BK-9999"},changes=new{series="No partial save"}}));Check(store.Read().Revision==before&&store.Read().State.Books.All(b=>b.Series==""),"bulk edit is atomic on stale/deleted selection");Reject(()=>Change("bulkEditBooks",new{copyIds=new[]{"BK-0001"},changes=new{isbn="9780141439518"}}));
  Change("bulkEditBooks",new{copyIds=store.Read().State.Books.Where(b=>!b.Archived).Select(b=>b.Id).ToArray(),changes=new{series="Shared series",publisher="",collectionId="general"}});Check(store.Read().State.Books.Where(b=>!b.Archived).All(b=>b.Series=="Shared series")&&store.Read().State.Loans.Count==2,"bulk metadata edit preserves circulation");
  using var accounts=new BorrowerAccounts(directory);var account=accounts.Register(new("reader","long-valid-passphrase","Reader","reader@example.com",""));account=accounts.Approve(new(account.Id,"","BR-0001"),store);var readerId=account.ReaderId;var old=accounts.Login(new("reader","long-valid-passphrase"));accounts.Block(account.Id);Change("removeBorrower",new{borrowerId="BR-0001"});
  var pending=accounts.Unblock(account.Id);Check(pending.Status=="pending"&&pending.ReaderId==""&&accounts.Resolve(old)==null,"unblock requires fresh approval and never revives old sessions");var pendingSession=accounts.Login(new("reader","long-valid-passphrase"));Reject(()=>store.AccountView(accounts.Resolve(pendingSession)!));
  account=accounts.Approve(new(account.Id,readerId,"",RestoreBorrower:true),store);Check(!store.Read().State.Borrowers.Single(b=>b.Id=="BR-0001").Archived&&store.Read().State.RecycleBin.All(r=>r.Borrower?.Id!="BR-0001"),"unblock restores deleted linked borrower and preserves history");Check(!store.Read().State.Borrowers.Single(b=>b.Id=="BR-0001").ReminderConsent,"restored borrower reminder permission starts off");
  accounts.Block(account.Id);Change("removeBorrower",new{borrowerId="BR-0001"});accounts.Unblock(account.Id);account=accounts.Approve(new(account.Id,readerId,"",CreateBorrower:true),store);Check(account.BorrowerId!="BR-0001"&&account.ReaderId==readerId,"unblocked account can explicitly replace removed borrower and relink reading profile");
  accounts.Block(account.Id);Change("removeBorrower",new{borrowerId=account.BorrowerId});accounts.Unblock(account.Id);var replacementBorrower=Change("addBorrower",new{name="Replacement operational record",contact="reader@example.com"}).GetProperty("id").GetString()!;account=accounts.Approve(new(account.Id,BorrowerId:replacementBorrower),store);Check(account.ReaderId==readerId&&account.BorrowerId==replacementBorrower,"account approval can relink its own hidden private profile by selecting an operational borrower");
  var restoredBackup=JsonSerializer.Deserialize<LibraryState>(JsonSerializer.Serialize(store.Read().State,Library.Json),Library.Json)!;Library.Validate(restoredBackup);Check(restoredBackup.RecycleBin.Count==2,"recycle bin survives library backup round trip");
  // Test planner and worker with a fake sender: no external email is sent.
  var sender=new FakeSender();using(var reminders=new Reminders(directory,protection,store,sender)){
   var config=new ReminderConfiguration{Enabled=true,Host="smtp.example.com",FromEmail="owner@example.com",Username="owner@example.com",Password="fake-private-app-password",SendHour=0};reminders.Save(config);Check(!JsonSerializer.Serialize(reminders.Status(),Library.Json).Contains("fake-private-app-password"),"SMTP credentials never returned in settings status");Check(!File.ReadAllText(Path.Combine(directory,"reminder-settings.protected")).Contains("fake-private-app-password"),"SMTP settings encrypted at rest");
   var borrower=store.Read().State.Borrowers.Find(b=>b.Id==account.BorrowerId)!;Change("updateBorrower",new{borrowerId=borrower.Id,name=borrower.Name,contact="reader@example.com",reminderConsent=true});Change("checkout",new{copyId="BK-0001",borrowerId=borrower.Id,checkoutDate=Library.Today,dueDate=Library.Today});
   await reminders.Run(DateTimeOffset.Now,default);await reminders.Run(DateTimeOffset.Now,default);Check(sender.Count==1,"due reminder sent once across repeated scheduler checks");Change("returnBook",new{copyId="BK-0001"});await reminders.Run(DateTimeOffset.Now.AddDays(10),default);Check(sender.Count==1,"returned loan never receives overdue reminder");
   Change("checkout",new{copyId="BK-0001",borrowerId=borrower.Id,checkoutDate=Library.Today,dueDate=Library.Today});sender.Fail=true;await reminders.Run(DateTimeOffset.Now,default);await reminders.Run(DateTimeOffset.Now,default);Check(sender.Count==2,"ambiguous failed SMTP delivery is not automatically duplicated");
   config.Enabled=false;reminders.Save(config);await reminders.Run(DateTimeOffset.Now.AddDays(10),default);Check(sender.Count==2,"disabled reminder service sends nothing");
   var state=store.Read().State;var today=DateOnly.Parse(Library.Today);Check(Reminders.Plan(state,config,today.AddDays(-2)).Single().Stage=="before"&&Reminders.Plan(state,config,today.AddDays(7)).Single().Stage=="overdue","before due and overdue planning");state.Borrowers.Single(b=>b.Id==borrower.Id).ReminderConsent=false;Check(Reminders.Plan(state,config,today).Count==0,"no reminders without borrower permission");
  }
  using(var reopened=new Reminders(directory,protection,store,sender)){Check(!((JsonElement)Input(reopened.Status())).GetProperty("enabled").GetBoolean(),"reminder settings and delivery ledger persist across restart");}
 }
 sealed class FakeSender:IReminderSender {public int Count;public bool Fail;public Task Send(ReminderConfiguration settings,ReminderMail mail,CancellationToken stop){Count++;if(Fail)throw new SmtpException("simulated interrupted send");return Task.CompletedTask;}}
}
